import NextAuth, { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import jwt from "jsonwebtoken";

// Define the shape of the user object returned from your backend
// and the shape of the JWT payload your backend creates.
interface BackendUser {
  id: string;
  email: string;
  role: "admin" | "salesperson";
  backendToken: string; // We'll attach the raw token here
}

interface BackendJwtPayload {
  id: string;
  email: string;
  role: "admin" | "salesperson";
}

export const authOptions: NextAuthOptions = {
  // We are replacing the other providers with a single CredentialsProvider
  providers: [
    CredentialsProvider({
      // The name to display on the sign in form (e.g. "Sign in with...")
      name: "Credentials",
      // The credentials is used to generate a suitable form on the sign in page.
      credentials: {
        email: {
          label: "Email",
          type: "text",
          placeholder: "john.doe@example.com",
        },
        password: { label: "Password", type: "password" },
      },
      // This is the core function where you authenticate the user
      async authorize(credentials, req): Promise<any> {
        if (!credentials?.email || !credentials?.password) {
          return null;
        }

        try {
          // Call your backend's login endpoint
          const res = await fetch(
            `${process.env.NEXT_PUBLIC_API_URL}/auth/login`,
            {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                email: credentials.email,
                password: credentials.password,
              }),
            },
          );

          // If the login fails (e.g., 401 Unauthorized), return null
          if (!res.ok) {
            console.error("Login failed:", await res.text());
            return null;
          }

          // Your backend returns { message: "...", token: "Bearer <jwt>" }
          const data = await res.json();
          const backendToken = data.token;

          if (backendToken) {
            // Decode the token to get user info (id, email, role)
            const tokenPayload = jwt.decode(
              backendToken.replace("Bearer ", ""),
            ) as BackendJwtPayload;

            // The authorize function must return a user object.
            // We'll construct it from the decoded token payload and
            // attach the raw token for use in other callbacks.
            return {
              id: tokenPayload.id,
              email: tokenPayload.email,
              role: tokenPayload.role,
              backendToken: backendToken,
            } as BackendUser;
          }

          // Return null if authentication fails
          return null;
        } catch (error) {
          console.error("Authorize error:", error);
          return null;
        }
      },
    }),
  ],

  // We must use the 'jwt' session strategy because we are not using a database adapter
  session: {
    strategy: "jwt",
    maxAge: 8 * 60 * 60, // 8 hours, should match your backend's token expiry
  },

  // The MongoDB adapter is no longer needed. Your backend is the source of truth for users.
  // adapter: MongoDBAdapter(clientPromise),

  pages: {
    signIn: "/login",
    signOut: "/login",
  },

  callbacks: {
    /**
     * This callback is called whenever a JWT is created or updated.
     * The `user` object is only passed on the initial sign-in.
     */
    async jwt({ token, user }) {
      // On initial sign-in, the 'user' object is the one returned from the 'authorize' function.
      if (user) {
        const backendUser = user as BackendUser;
        token.userId = backendUser.id;
        token.role = backendUser.role;
        token.accessToken = backendUser.backendToken; // This is your backend's JWT
      }
      return token;
    },

    /**
     * This callback is called whenever a session is checked.
     * We are taking the data from the token and passing it to the client.
     */
    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.userId as string;
        session.user.role = token.role as "admin" | "salesperson";
      }
      // This is the token that your frontend will use to make authenticated API calls
      session.accessToken = token.accessToken as string;

      return session;
    },
  },

  secret: process.env.NEXTAUTH_SECRET,
  debug: process.env.NODE_ENV === "development",
};

export default NextAuth(authOptions);
